        "EP_0010_E02"
      ],
      "check_spec": {
        "kind": "numeric",
        "fact_id": "EP_0010_F07",
        "metric": "medical_care_ratio",
        "period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "89.1",
        "unit": "percent"
      }
    },
    {
      "claim_id": "C4",
      "text": "Medical costs for COMPANY_10 increased by 18.85% (calculated from $264,185 million to $313,995 million) from 2024 to 2025, as shown in Item 7. The filing summary table reports a rounded 19% increase. This significant increase contributed to the decline in earnings from operations.",
      "evidence_ids": [
        "EP_0010_E01"
      ],
      "check_spec": {
        "kind": "percentage_change",
        "from_fact_id": "EP_0010_F06",
        "to_fact_id": "EP_0010_F05",
        "metric": "medical_costs",
        "from_period": {
          "label": "FY2024",
          "start": "2024-01-01",
          "end": "2024-12-31"
        },
        "to_period": {
          "label": "FY2025",
          "start": "2025-01-01",
          "end": "2025-12-31"
        },
        "value": "18.85",
        "unit": "percent"
      }
    }
  ],
  "rationale": "COMPANY_10 experienced a substantial decline in earnings from operations and a deterioration in its medical care ratio, despite revenue growth. The significant increase in medical costs, driven by factors such as IRA-driven impacts on Medicare Part D plans and elevated medical cost trends, directly impacted profitability. The MCR increase from 85.5% to 89.1% indicates a higher proportion of premium revenue consumed by medical costs, compressing margins. The company also faces competitive risks and challenges in innovation, as highlighted in Item 1A. These factors suggest a deteriorating financial performance and increased operational risks, warranting a SELL recommendation."
}

